from pathlib import Path
import numpy as np, vtk, matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt, matplotlib.tri as mtri
from vtk.util.numpy_support import numpy_to_vtk,numpy_to_vtkIdTypeArray,vtk_to_numpy
from PIL import Image
out=Path('outputs/SoftwareX_LaTeX');d=np.load('work/paper-figures/flow_solution.npz');v=d['values'];t=d['tetrahedra'];p=vtk.vtkPoints();p.SetData(numpy_to_vtk(v[:3].T.copy(),deep=True));g=vtk.vtkUnstructuredGrid();g.SetPoints(p);c=vtk.vtkCellArray();c.SetCells(len(t),numpy_to_vtkIdTypeArray(np.c_[np.full(len(t),4),t].astype(np.int64).ravel(),deep=True));g.SetCells(vtk.VTK_TETRA,c);arr=numpy_to_vtk(v[3].copy(),deep=True);arr.SetName('speed');g.GetPointData().SetScalars(arr)
plane=vtk.vtkPlane();plane.SetOrigin(0,2.47,0);plane.SetNormal(0,1,0);cut=vtk.vtkCutter();cut.SetCutFunction(plane);cut.SetInputData(g);cut.Update();tri=vtk.vtkTriangleFilter();tri.SetInputConnection(cut.GetOutputPort());tri.Update();s=tri.GetOutput();pts=vtk_to_numpy(s.GetPoints().GetData());vals=vtk_to_numpy(s.GetPointData().GetScalars());faces=vtk_to_numpy(s.GetPolys().GetData()).reshape(-1,4)[:,1:]
fig,axs=plt.subplots(1,2,figsize=(9,5.4),gridspec_kw={'width_ratios':[1,1.1]});ax=axs[0];im=ax.tripcolor(mtri.Triangulation(pts[:,0],pts[:,2],faces),vals,cmap='viridis',shading='gouraud',vmin=0,vmax=.4,rasterized=True);ax.set(aspect='equal',xlim=(0,5),ylim=(0,5),xlabel='x (mm)',ylabel='z (mm)',title='');cb=fig.colorbar(im,ax=ax,fraction=.045,pad=.035);cb.set_label('Speed (mm/s)',fontsize=11);ax.set_title('(a) Pore flow',fontsize=14,pad=36)
ax.text(.5,1.04,'Outlet: p = 0 Pa',ha='center',transform=ax.transAxes,fontsize=11);ax.text(.5,-.20,'Inlet: p = 0.01 Pa',ha='center',transform=ax.transAxes,fontsize=11)
# Independent rendering of the actual saved solid solution, with a legible common palette.
ed=np.load('work/paper-figures/elastic_solution.npz');ev=ed['values'];et=ed['tetrahedra'];ep=vtk.vtkPoints();ep.SetData(numpy_to_vtk(ev[:3].T.copy(),deep=True));eg=vtk.vtkUnstructuredGrid();eg.SetPoints(ep);ec=vtk.vtkCellArray();ec.SetCells(len(et),numpy_to_vtkIdTypeArray(np.c_[np.full(len(et),4),et].astype(np.int64).ravel(),deep=True));eg.SetCells(vtk.VTK_TETRA,ec);ea=numpy_to_vtk(ev[3].copy(),deep=True);ea.SetName('displacement');eg.GetPointData().SetScalars(ea)
lut=vtk.vtkLookupTable();lut.SetNumberOfTableValues(256);lut.SetRange(0,5.2)
for i in range(256):lut.SetTableValue(i,*plt.get_cmap('viridis')(i/255))
lut.Build();mapper=vtk.vtkDataSetMapper();mapper.SetInputData(eg);mapper.SetLookupTable(lut);mapper.SetScalarRange(0,5.2);actor=vtk.vtkActor();actor.SetMapper(mapper);actor.GetProperty().LightingOff();ren=vtk.vtkRenderer();ren.SetBackground(1,1,1);ren.AddActor(actor);cam=ren.GetActiveCamera();cam.SetPosition(11,-15,10);cam.SetFocalPoint(2.5,2.5,2.5);cam.SetViewUp(0,0,1);cam.ParallelProjectionOn();ren.ResetCamera();cam.Zoom(1.12);win=vtk.vtkRenderWindow();win.SetOffScreenRendering(1);win.SetSize(900,900);win.AddRenderer(ren);win.Render();grab=vtk.vtkWindowToImageFilter();grab.SetInput(win);grab.Update();wr=vtk.vtkPNGWriter();wr.SetInputConnection(grab.GetOutputPort());wr.SetFileName('work/paper-figures/elastic_field.png');wr.Write();win.Finalize()
axs[1].imshow(Image.open('work/paper-figures/elastic_field.png'));axs[1].axis('off');axs[1].set_title('(b) Solid elasticity',fontsize=14,pad=36);axs[1].text(.5,1.04,'Top: z displacement = −5 μm',ha='center',transform=axs[1].transAxes,fontsize=11);axs[1].text(.5,-.07,'Bottom: fixed',ha='center',transform=axs[1].transAxes,fontsize=11);cb=fig.colorbar(plt.cm.ScalarMappable(norm=plt.Normalize(0,5.2),cmap='viridis'),ax=axs[1],fraction=.045,pad=.005);cb.set_label('Displacement (μm)',fontsize=11)
fig.subplots_adjust(left=.065,right=.94,bottom=.20,top=.79,wspace=.35);fig.savefig(out/'fig4_comsol.png',dpi=300,facecolor='white');plt.close(fig)
print('COMSOL result figure written')
